var sortVowels = function(s) {
    const vowelsSet = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']);
    const vowels = [];
    for (const c of s) {
        if (vowelsSet.has(c)) vowels.push(c);
    }
    vowels.sort();
    const chars = s.split('');
    let vIdx = 0;
    for (let i = 0; i < chars.length; i++) {
        if (vowelsSet.has(chars[i])) {
            chars[i] = vowels[vIdx++];
        }
    }
    return chars.join('');
};
